  beforeAll(async () => {
    dataSource = await new DataSource(buildDataSourceOptions(testEnv.DATABASE_URL)).initialize();
  });

  afterAll(async () => {
    // Leave the schema fully migrated for the other suites.
    await dataSource.runMigrations();
    await dataSource.destroy();
