      PORT: 3000,
      LOG_LEVEL: 'info',
    });
  });

  it('defaults DATABASE_URL to the docker-compose database outside production', () => {
    expect(parseEnv({}).DATABASE_URL).toBe(
      'postgres://artifact_hub:artifact_hub@localhost:5432/artifact_hub',
    );
