import type { User } from '../users/user.entity.js';
import type { Session } from './session.entity.js';

/** Who is performing an action. Every service method that touches user data takes one. */
export interface Actor {
  userId: string;
  via: 'web' | 'mcp';
}

export interface RequestAuth {
  actor: Actor;
  sessionId: string;
}

declare global {
  namespace Express {
    interface Request {
      /** Set by `SessionGuard` on authenticated routes. */
      auth?: RequestAuth;
    }
  }
}

export interface ClientInfo {
  ip: string | null;
  userAgent: string | null;
}

export interface LoginContext extends ClientInfo {
  /** The session token the browser already holds, if any; it is revoked on login. */
  previousToken?: string;
}

export interface IssuedSession {
  token: string;
  expiresAt: Date;
}

export interface ResolvedSession {
  /** Includes `user`. */
  session: Session;
  /** True when the expiry was extended, so the cookie must be re-sent with the new expiry. */
  extended: boolean;
}

export interface AuthResult {
  user: User;
  session: IssuedSession;
}

export type CsrfDecision = 'allow' | 'foreign_origin' | 'missing_origin';
EOF
