import type { User } from '@artifact-hub/shared';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { currentUserQueryKey, fetchCurrentUser, login, logout, signup } from './auth-api.ts';

export function useCurrentUser() {
  return useQuery({
    queryKey: currentUserQueryKey,
    queryFn: fetchCurrentUser,
    // Changes only through login/signup/logout (which update the cache) or a 401.
    staleTime: Infinity,
  });
}

function useSetCurrentUser() {
  const queryClient = useQueryClient();
  return (user: User) => queryClient.setQueryData(currentUserQueryKey, user);
}

export function useLogin() {
  const setCurrentUser = useSetCurrentUser();
  return useMutation({ mutationFn: login, onSuccess: setCurrentUser });
}

export function useSignup() {
  const setCurrentUser = useSetCurrentUser();
  return useMutation({ mutationFn: signup, onSuccess: setCurrentUser });
}

export function useLogout() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: logout,
    onSuccess: () => {
      // Drop everything cached for this user, then mark the session as signed out.
      queryClient.clear();
      queryClient.setQueryData(currentUserQueryKey, null);
    },
  });
}
EOF
cat > apply-server-error.ts <<'EOF'
import type { FieldValues, Path, UseFormSetError } from 'react-hook-form';
import { describeError, isApiError } from '@/lib/api/api-error.ts';

/**
 * Shows a failed submission on the form: validation issues next to their fields, everything
 * else as a form-level message (`errors.root.server`).
 */
export function applyServerError<T extends FieldValues>(
  error: unknown,
  setError: UseFormSetError<T>,
  fields: readonly Path<T>[],
): void {
  if (isApiError(error)) {
    const issues = error.fieldIssues.filter((issue) => fields.includes(issue.path as Path<T>));
    for (const issue of issues) setError(issue.path as Path<T>, { message: issue.message });
    if (issues.length > 0) return;
  }
  setError('root.server', { message: describeError(error) });
}
EOF
